async function 加密对接文件信息(Json) {
    if (!开发者UID || !开发者密码) {
        alert('请先登录', false);
        return;
    }
    
    try {
        const params = {
            action: 'encrypt_info_aes256cbc',
            content:JSON.stringify(Json),
            password: 开发者安全密码
        };

        const result = await POSTPHP(开发者UID, 开发者密码, 开发者Token, 获取API链接('api.php'), params);
        if (result.success) {
            return {
                success: true,
                data: result.data,
                message: '获取成功'
            };
        } else {
        return {
            success: false,
            message: result.message,
            error: true
        };
        }
    } catch (error) {
        return {
            success: false,
            message: error.message,
            error: true
        };
    }
}





