function 应用事例_签名名(t) {
    return ({'0':'不签名','1':'MD5','2':'SHA512','3':'CRC32','4':'SHA256','5':'RIPEMD-160','6':'SHA1','7':'SHA224','8':'SHA384','9':'SHA3-512','10':'SHA3-256','11':'SHA3-224','12':'JiYan-Sign（HMAC-SHA256）','13':'JiYan-Sign+（双段 HMAC）'})[String(t||'0')] || ('类型'+t);
}
function 应用事例_加密名(t) {
    return ({'0':'不加密','1':'AES-256-CBC','2':'自定义 Base64 编码集','3':'极验 EnvProto','4':'JiYan-Seal v1','5':'AES-256-CBC + HMAC-SHA256'})[String(t||'0')] || ('方式'+t);
}
function 应用事例_签名串(params, signKey) {
    const keys = Object.keys(params);
    let values = keys.map(k => params[k]).join('');
    values += (signKey || '');
    return { order: keys.join(' + '), raw: values };
}
function 应用事例_响应签名串(success, message, data, signKey) {
    const json = JSON.stringify(data || {});
    return String(success ? 'true' : 'false') + String(message || '') + json + String(signKey || '');
}

async function 打开应用事例() {
    if (!开发者UID || !开发者密码) {
        alert('请先登录', false);
        return;
    }
    const old = document.querySelector('.app-example-modal');
    if (old) old.remove();
    等待动画('正在读取应用配置...');
    let apps = [];
    try {
        const result = await POSTPHP(开发者UID, 开发者密码, 开发者Token, 获取API链接('app.php'), {
            action: 'get_apps', password: 开发者安全密码, page: 1, limit: 100
        });
        删除等待动画();
        if (!result.success) {
            alert(result.message || '读取应用失败', false);
            return;
        }
        apps = result.data.apps || [];
    } catch (e) {
        删除等待动画();
        alert(e.message || '读取应用失败', false);
        return;
    }
    if (!apps.length) {
        alert('请先到「应用实例」创建一个应用', false);
        return;
    }
    const modal = document.createElement('div');
    modal.className = 'app-example-modal 弹窗遮罩';
    const options = apps.map(a => `<option value="${a.app_id}">${escapeHtml(a.app_name)} (ID ${a.app_id})</option>`).join('');
    modal.innerHTML = `
        <div class="弹窗背景" style="max-width:720px;width:calc(100vw - 24px);">
            <div class="弹窗头部">
                <div class="弹窗头部文字">
                    <i class="fas fa-code" style="color:#28a745;"></i>
                    <h4>应用事例</h4>
                </div>
                <button onclick="this.closest('.app-example-modal').remove()" class="弹窗头部关闭按钮">&times;</button>
            </div>
            <div class="弹窗内部" style="max-height:70vh;overflow:auto;">
                <div style="font-size:12px;color:#666;margin-bottom:12px;line-height:1.7;">
                    按当前应用的加密方式、签名方式、收费/免费模式生成可直接复制的请求串。SDK 地址固定为 <code>/api/env/key.php</code>。
                </div>
                <div style="margin-bottom:8px;font-size:13px;font-weight:500;">选择应用</div>
                <select id="exampleAppSelect" style="width:100%;padding:10px 12px;border:1px solid #ddd;border-radius:4px;margin-bottom:12px;">${options}</select>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;">
                    <input id="exampleCard" placeholder="卡密（免费模式可留空）" style="padding:10px 12px;border:1px solid #ddd;border-radius:4px;">
                    <input id="exampleDevice" placeholder="设备码 / 机器码" value="DEMO-DEVICE-001" style="padding:10px 12px;border:1px solid #ddd;border-radius:4px;">
                </div>
                <div id="exampleMeta" style="background:#f8f9fa;border:1px solid #f0f0f0;border-radius:6px;padding:10px 12px;font-size:12px;color:#555;line-height:1.8;margin-bottom:12px;"></div>
                <pre id="exampleOut" style="white-space:pre-wrap;word-break:break-all;background:#111;color:#d6f5d6;padding:12px;border-radius:8px;font-size:12px;min-height:180px;"></pre>
            </div>
            <div class="弹窗底部">
                <button onclick="this.closest('.app-example-modal').remove()" style="padding:8px 16px;background:#f8f9fa;color:#666;border:1px solid #ddd;border-radius:20px;cursor:pointer;font-size:13px;">关闭</button>
                <button onclick="应用事例_生成()" style="padding:8px 16px;background:#28a745;color:#fff;border:none;border-radius:20px;cursor:pointer;font-size:13px;">生成事例</button>
                <button onclick="应用事例_实测()" style="padding:8px 16px;background:#1e90ff;color:#fff;border:none;border-radius:20px;cursor:pointer;font-size:13px;">实测验证</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    window.__JY_EXAMPLE_APPS = apps;
    应用事例_生成();
    document.getElementById('exampleAppSelect').onchange = 应用事例_生成;
}

function 应用事例_当前应用() {
    const id = document.getElementById('exampleAppSelect')?.value;
    const apps = window.__JY_EXAMPLE_APPS || [];
    return apps.find(a => String(a.app_id) === String(id)) || apps[0] || null;
}

function 应用事例_生成() {
    const app = 应用事例_当前应用();
    const out = document.getElementById('exampleOut');
    const meta = document.getElementById('exampleMeta');
    if (!app || !out) return;
    const card = (document.getElementById('exampleCard')?.value || '').trim();
    const device = (document.getElementById('exampleDevice')?.value || 'DEMO-DEVICE-001').trim();
    const enc = String(app.encryption_format || '0');
    const signType = String(app.sign_type || '0');
    const signKey = String(app.sign_key || '');
    const billing = String(app.billing_mode || '0');
    const apiKey = String(app.api_key || '');
    const rc = (typeof generateRequestCode === 'function') ? generateRequestCode() : 'ABC123XYZ789';
    const params = {
        action: 'use_card',
        card: card || (billing === '1' ? 'FREE-MODE' : 'YOUR_CARD_KEY'),
        device_id: device,
        token: 开发者Token || '',
        rc: rc
    };
    const signInfo = 应用事例_签名串(params, signKey);
    let signature = '';
    if (signType !== '0' && typeof 签名计算 === 'function') {
        signature = 签名计算(signType, signInfo.raw);
        params.signature = signature;
    }
    const query = Object.keys(params).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(params[k])).join('&');
    const respRaw = 应用事例_响应签名串(true, '卡密验证成功', { '到期时间': '2026-12-31 23:59:59', 在线人数: 1, game_uids: [], rc: rc }, signKey);
    if (meta) {
        meta.innerHTML =
            '<div><b>应用</b> ' + escapeHtml(app.app_name) + ' / ID ' + escapeHtml(String(app.app_id)) + '</div>' +
            '<div><b>计费</b> ' + (billing === '1' ? '免费模式（任意卡密都可通过）' : '正常计费（必须真实卡密）') + '</div>' +
            '<div><b>加密</b> ' + 应用事例_加密名(enc) + ' · 密钥 ' + escapeHtml(apiKey || '(空)') + '</div>' +
            '<div><b>签名</b> ' + 应用事例_签名名(signType) + ' · 密钥 ' + escapeHtml(signKey || '(空)') + '</div>' +
            '<div><b>请求签名串</b> 所有参数 value 按出现顺序拼接 + 签名密钥</div>' +
            '<div><b>响应签名串</b> true/false + message + JSON.stringify(data) + 签名密钥</div>';
    }
    out.textContent =
        'POST /api/env/key.php\n' +
        'Content-Type: application/json\n\n' +
        '1) 明文参数（加密前）\n' + query + '\n\n' +
        '2) 请求签名原文\n' + signInfo.raw + '\n' +
        (signature ? ('3) 请求签名结果 [' + 应用事例_签名名(signType) + ']\n' + signature + '\n\n') : '3) 当前应用关闭签名校验\n\n') +
        '4) JSON 外壳\n' +
        JSON.stringify({
            developer_username: 开发者UID,
            app_id: String(app.app_id),
            iv: enc === '1' ? '<Base64(16字节IV)>' : '',
            data: enc === '0' ? query : '<按加密方式处理后的 data>'
        }, null, 2) + '\n\n' +
        '5) 响应签名原文示例\n' + respRaw + '\n\n' +
        'JNI 调用对应：\n' +
        'EnvSDK::set_api_url("https://你的域名/api/env/");\n' +
        'EnvSDK_API::卡密验证::使用卡密(卡密, 提示);\n' +
        'EnvSDK_API::卡密验证::解绑卡密(卡密, 提示);';
}

async function 应用事例_实测() {
    const app = 应用事例_当前应用();
    if (!app) return;
    const prevEnc = window.当前选中的应用加密格式;
    const prevKey = window.当前选中的应用对接密钥;
    const prevSignT = window.当前应用的签名类型;
    const prevSignK = window.当前应用的签名密钥;
    const prevId = window.当前选中的应用ID;
    window.当前选中的应用ID = String(app.app_id);
    window.当前选中的应用加密格式 = String(app.encryption_format || '0');
    window.当前选中的应用对接密钥 = String(app.api_key || '');
    window.当前应用的签名类型 = String(app.sign_type || '0');
    window.当前应用的签名密钥 = String(app.sign_key || '');
    const card = (document.getElementById('exampleCard')?.value || '').trim();
    const device = (document.getElementById('exampleDevice')?.value || 'DEMO-DEVICE-001').trim();
    等待动画('正在按当前加密/签名实测...');
    try {
        const result = await POSTKEYPHP({
            action: 'use_card',
            card: card || 'FREE-MODE',
            device_id: device
        });
        删除等待动画();
        const out = document.getElementById('exampleOut');
        if (out) out.textContent = (out.textContent || '') + '\n\n==== 实测结果 ====\n' + JSON.stringify(result, null, 2);
        alert(result && result.success ? (result.message || '验证成功') : ((result && result.message) || '验证失败'), !!(result && result.success));
    } catch (e) {
        删除等待动画();
        alert(e.message || '实测失败', false);
    } finally {
        window.当前选中的应用加密格式 = prevEnc;
        window.当前选中的应用对接密钥 = prevKey;
        window.当前应用的签名类型 = prevSignT;
        window.当前应用的签名密钥 = prevSignK;
        window.当前选中的应用ID = prevId;
    }
}